package org.novasos.healthysv2.laboratory;
import static org.assertj.core.api.Assertions.*;import java.math.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;
class LabOrderTests{
 @Test void executesOrderSpecimenAndResultWorkflow(){UUID professional=UUID.randomUUID(),exam=UUID.randomUUID();var order=LabOrder.create(UUID.randomUUID(),null,professional,UUID.randomUUID(),"URGENT");var ordered=order.addItem(exam,"Fasting");var specimen=order.collect(ordered.getId(),"SP-001","BLOOD",Instant.now(),professional);order.receive(specimen.getId());var result=order.createResult(professional,Instant.now(),"Automated analysis");result.addItem(ordered,UUID.randomUUID(),null,"5.4","mmol/L",new BigDecimal("3.5"),new BigDecimal("6.0"),null,"NORMAL");order.validateResult(result.getId(),professional);assertThat(order.getStatus()).isEqualTo("COMPLETED");assertThat(ordered.getStatus()).isEqualTo("COMPLETED");assertThat(specimen.getStatus()).isEqualTo("RECEIVED");assertThat(result.getStatus()).isEqualTo("FINAL");assertThat(result.getValidatedAt()).isNotNull();assertThatThrownBy(()->order.addItem(UUID.randomUUID(),null)).isInstanceOf(IllegalStateException.class);}
 @Test void refusesResultsWithoutSpecimensOrValues(){UUID professional=UUID.randomUUID();var order=LabOrder.create(UUID.randomUUID(),null,professional,null,"ROUTINE");var item=order.addItem(UUID.randomUUID(),null);assertThatThrownBy(()->order.createResult(professional,null,null)).isInstanceOf(IllegalStateException.class);order.collect(item.getId(),"SP-002","BLOOD",null,professional);var result=order.createResult(professional,null,null);assertThatThrownBy(()->order.validateResult(result.getId(),professional)).isInstanceOf(IllegalStateException.class);}
}
